def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = 18.0 if hp > 3 else 42.0
        return float(min(budget, base))

    prev_bids = []
    strong_prev = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 120:
                strong_prev.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if scarcity == 2:
        urgency += 2
    elif scarcity == 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        target = max(110.0, highest_prev + 3.0)
    elif urgency >= 4:
        if highest_prev >= 120:
            target = highest_prev + 2.0
        else:
            target = max(72.0, avg_prev * 0.7 + 8.0)
    elif urgency >= 2:
        if highest_prev >= 130:
            target = 58.0
        else:
            target = max(34.0, min(68.0, avg_prev * 0.45 + 6.0))
    else:
        if strong_prev:
            target = 22.0
        else:
            target = max(18.0, min(40.0, avg_prev * 0.35 + 4.0))

    reserve_days = 10 - day
    if reserve_days < 0:
        reserve_days = 0
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(budget, budget / (reserve_days + 1) * 1.6)

    if urgency >= 5:
        final_bid = min(budget, max(target, soft_cap))
    else:
        final_bid = min(budget, min(target, soft_cap))

    if hp <= 2 or no_water >= 2:
        final_bid = min(budget, max(final_bid, highest_prev + 2.5, 95.0))

    if final_bid < 0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
