    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 70.0
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)
    if day_context['supply'] < WATER_REQ * 1.5:
        return min(my_status['budget'], max(avg_prev + 5.0, 85.0))
    return min(my_status['budget'], max(avg_prev, 75.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        max_prev = max(yesterday_bids)
    else:
        max_prev = 0
    # Supply scarcity multiplier: lower supply => need higher bid
    supply_factor = 1.0 + (25 - supply) / 20.0  # min 1.0, max 1.5
    if max_prev >= DAILY_SALARY * 0.85:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.95 * supply_factor)
        else:
            return min(budget, DAILY_SALARY * 0.3 * supply_factor)
    else:
        if hp <= 2:
            return min(budget, max(DAILY_SALARY * 0.5, max_prev + 2.0) * supply_factor)
        else:
            return min(budget, max(DAILY_SALARY * 0.4, max_prev + 1.5) * supply_factor)
